const menuButton=document.querySelector('.menu-toggle');const nav=document.querySelector('#nav');if(menuButton&&nav){menuButton.addEventListener('click',()=>{const open=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}))}
const vehicles={moto:{title:'Sua moto mais segura e protegida',src:'/assets/original/moto.png',alt:'Moto protegida pela Guard'},carro:{title:'Seu carro mais seguro e protegido',src:'/assets/original/carro.png',alt:'Carro protegido pela Guard'},van:{title:'Sua van mais segura e protegida',src:'/assets/original/van.png',alt:'Van protegida pela Guard'}};document.querySelectorAll('.vehicle-tabs button').forEach(button=>button.addEventListener('click',()=>{const vehicle=vehicles[button.dataset.type];document.querySelector('#vehicle-title').textContent=vehicle.title;const image=document.querySelector('#vehicle-image');image.src=vehicle.src;image.alt=vehicle.alt;document.querySelectorAll('.vehicle-tabs button').forEach(item=>{const active=item===button;item.classList.toggle('active',active);item.setAttribute('aria-selected',String(active))})}));
const testimonials=[['Precisei utilizar por conta de um roubo, resolveram meu problema na hora!','Millenium Peças'],['Excelente atendimento, muito cuidado e atenção com os clientes. Nota 10.','Celio Oliveira'],['Atendimento diferenciado, muito solícitos e cumprem o acordado.','Thiago Moises'],['Sou associada há anos e sempre fui muito bem atendida.','Sara Loren'],['São éticos, profissionais e estão sempre prontos para ajudar.','Joyce Ferreira']];let testimonialIndex=0;const text=document.querySelector('#testimonial-text');const author=document.querySelector('#testimonial-author');const dots=document.querySelector('.dots');function renderTestimonial(){text.textContent=testimonials[testimonialIndex][0];author.textContent=testimonials[testimonialIndex][1];dots.querySelectorAll('button').forEach((dot,index)=>dot.classList.toggle('active',index===testimonialIndex))}testimonials.forEach((_,index)=>{const dot=document.createElement('button');dot.setAttribute('aria-label',`Mostrar depoimento ${index+1}`);dot.addEventListener('click',()=>{testimonialIndex=index;renderTestimonial()});dots.appendChild(dot)});document.querySelector('.carousel-btn.prev').addEventListener('click',()=>{testimonialIndex=(testimonialIndex-1+testimonials.length)%testimonials.length;renderTestimonial()});document.querySelector('.carousel-btn.next').addEventListener('click',()=>{testimonialIndex=(testimonialIndex+1)%testimonials.length;renderTestimonial()});renderTestimonial();
const toggle=document.querySelector('#toggle-password');const password=document.querySelector('#senha');if(toggle&&password){toggle.addEventListener('click',()=>{const show=password.type==='password';password.type=show?'text':'password';toggle.textContent=show?'Ocultar':'Mostrar'})}const loginForm=document.querySelector('#login-form');if(loginForm){loginForm.addEventListener('submit',event=>{event.preventDefault();loginForm.querySelector('.form-message').textContent='Não foi possível concluir o acesso. Verifique seus dados e tente novamente.'})}const forgot=document.querySelector('#forgot-link');if(forgot){forgot.addEventListener('click',event=>{event.preventDefault();loginForm.querySelector('.form-message').textContent='Entre em contato com a central de atendimento para recuperar o acesso.'})}
